local config = {
  ui_story_32250401_1_dialog_content = "Tiare!",
  ui_story_32250401_2_dialog_content = "Wh-What's going on? Is everyone okay? Where are the bodies?",
  ui_story_32250401_3_dialog_content = "They're dead... They're all dead.",
  ui_story_32250401_4_dialog_content = "All dead?",
  ui_story_32250401_5_dialog_content = "That can't be! What about Vice and Carleen? How did the Eclipsites manage to break in?",
  ui_story_32250401_6_dialog_content = "Vice and Carleen? Eclipsites?",
  ui_story_32250401_7_dialog_content = "What are you talking about, PlayerName? Because I'm talking about the poachers.",
  ui_story_32250401_8_dialog_content = "P-Poachers?",
  ui_story_32250401_9_dialog_content = "Yes. A band of poachers recently appeared in the forest, trapping and killing anything they could get their hands on...",
  ui_story_32250401_10_dialog_content = "More than a hundred animals were slaughtered last week, and the elder found even more bodies this morning...",
  ui_story_32250401_11_dialog_content = "So the bodies you mentioned are animal bodies?",
  ui_story_32250401_12_dialog_content = "Don't look so relieved. This is still a very serious problem.",
  ui_story_32250401_13_dialog_content = "Allow me to explain.",
  ui_story_32250401_14_dialog_content = "Elder! I didn't realize you were here too!",
  ui_story_32250401_15_dialog_content = "These poachers feel neither respect nor gratitude towards nature.",
  ui_story_32250401_16_dialog_content = "Their hunt is driven by nothing more than the market price of their prey...",
  ui_story_32250401_17_dialog_content = "They strip the animals of their most valuable parts and leave the rest to rot. What could have nourished countless living creatures now lies wasted in the most miserable way.",
  ui_story_32250401_18_dialog_content = "If left unchecked, these poachers will upset the natural balance of the forest. They must be stopped!",
  ui_story_32250401_19_dialog_content = "I see... Sorry for underestimating the seriousness of the situation. I just haven't dealt with anything like this before.",
  ui_story_32250401_20_dialog_content = "Do we know anything else about these poachers?",
  ui_story_32250401_21_dialog_content = "My foxes and I snuck into their camp earlier, and we found this matchbox.",
  ui_story_32250401_22_dialog_content = "This emblem...",
  ui_story_32250401_23_dialog_content = "I've seen it before! I think it belongs to a bar in Umbraton.",
  ui_story_32250401_24_dialog_content = "Pardon me, you two.",
  ui_story_32250401_25_dialog_content = "I don't believe I've seen your faces here before. Forgive me, but is this your first time here?",
  ui_story_32250401_26_dialog_content = "Of course it's our first time! You wouldn't be standing there if it wasn't—",
  ui_story_32250401_27_dialog_content = "A-Ahem!",
  ui_story_32250401_28_dialog_content = "P-Please excuse our rudeness and allow me to explain, sir. My mother is very ill, and a doctor in Longzhou told us that only bear bile could cure her disease.",
  ui_story_32250401_29_dialog_content = "We didn't know where to look for something like that, so we started asking around all of Umbraton. Thankfully, we ran into a kind-hearted barkeeper...",
  ui_story_32250401_30_dialog_content = "And the barkeeper told us that we might be able to buy some at a certain bar.",
  ui_story_32250401_31_dialog_content = "This one right here, see?",
  ui_story_32250401_32_dialog_content = "I see... Yes, I happen to visit that bar quite often.",
  ui_story_32250401_33_dialog_content = "\"The night when stars fall above the tower.\"",
  ui_story_32250401_34_dialog_content = "Huh? Oh, uh... \"The serpent stirs within the abyss.\"",
  ui_story_32250401_35_dialog_content = "Hahaha! Welcome, valued customer! Please, step inside!",
  ui_story_32250401_36_dialog_content = "When it comes to medicinal effects, the most potent bear bile is the golden variety, which is only produced by female bears after giving birth but before entering hibernation.",
  ui_story_32250401_37_dialog_content = "Fortunately for you, our shop just received a shipment straight from Northland.",
  ui_story_32250401_38_dialog_content = "You—",
  ui_story_32250401_39_dialog_content = "Th-That's wonderful! But just out of curiosity, what happens to the cubs after you kill the mother bear?",
  ui_story_32250401_40_dialog_content = "Heheh... No need to worry, my friend. The gourmands of Astra always have space on their tables for bear cubs.",
  ui_story_32250401_41_dialog_content = "!",
  ui_story_32250401_42_dialog_content = "Hey! Is anyone back there? How much longer am I supposed to wait for my order of two hundred black sparrow tongues?",
  ui_story_32250401_43_dialog_content = "Oh my, that's one of our best customers. Pardon me for just a moment, you two—",
  ui_story_32250401_44_dialog_content = "Why did you stop me, PlayerName? Isn't he the leader of the poachers?",
  ui_story_32250401_45_dialog_content = "Getting rid of the leader won't solve anything, since they can just appoint a new one. We need to stay calm and think of a more thorough solution.",
  ui_story_32250401_46_dialog_content = "But protecting the forest is my duty...",
  ui_story_32250401_47_dialog_content = "After seeing what they did to those animals, I can't help but feel outraged.",
  ui_story_32250401_48_dialog_content = "Can't believe that I just let them go so easily...",
  ui_story_32250401_49_option_content = "We're not letting them go.",
  ui_story_32250401_50_dialog_content = "We're being patient and waiting for the right time to strike. It's the smart thing to do, Tiare.",
  ui_story_32250401_51_dialog_content = "If we work together, I'm sure we can take down every single one of them!",
  ui_story_32250401_52_option_content = "You've already done so much.",
  ui_story_32250401_53_dialog_content = "Whether it's stealth, tracking, or even hunting, all of your strengths have been a huge help so far.",
  ui_story_32250401_54_dialog_content = "We would never have found that bar if you hadn't infiltrated their camp and found this matchbox.",
  ui_story_32250401_55_dialog_content = "And by eavesdropping in the bar, you even discovered their leader's location and their secret passphrase.",
  ui_story_32250401_56_dialog_content = "None of these would've been possible without you!",
  ui_story_32250401_57_dialog_content = "You make it sound like I've done something incredible.",
  ui_story_32250401_58_dialog_content = "So what exactly do you mean by a \"more thorough solution\"?",
  ui_story_32250401_59_dialog_content = "Are you going to report them to those \"police\" people?",
  ui_story_32250401_60_dialog_content = "Unfortunately, with so many different organizations controlling the streets of Umbraton, we can't exactly rely on the police.",
  ui_story_32250401_61_dialog_content = "But we can take it up with one of those organizations.",
  ui_story_32250401_62_dialog_content = "Boss! A letter suddenly appeared at the gate just now...",
  ui_story_32250401_63_dialog_content = "What do you mean, \"suddenly appeared\"?",
  ui_story_32250401_64_dialog_content = "Well, no one was able to get a good look at whoever dropped it off...",
  ui_story_32250401_65_dialog_content = "Humph, a bunch of worthless morons. Hand it here!",
  ui_story_32250401_66_dialog_content = "Yes, sir!",
  ui_story_32250401_67_dialog_content = "... Unbelievable!",
  ui_story_32250401_68_dialog_content = "Wh-What's the matter, boss?",
  ui_story_32250401_69_dialog_content = "... It's a warning.",
  ui_story_32250401_70_dialog_content = "According to this, someone noticed how well our underground fighting ring has been doing, and now they want a piece of the action.",
  ui_story_32250401_71_dialog_content = "It says they're planning some sort of beast-fighting arena!",
  ui_story_32250401_72_dialog_content = "People versus animals, huh? That's not a bad idea!",
  ui_story_32250401_73_dialog_content = "What are you, nuts? If they pull this off, our business is as good as dead!",
  ui_story_32250401_74_dialog_content = "Y-Yeah, you're right... This is really bad, boss!",
  ui_story_32250401_75_dialog_content = "Still, there's a chance this letter's just a bunch of baloney... This is Umbraton after all, right?",
  ui_story_32250401_76_dialog_content = "I know that, you idiot! Looks like I'll have to go check things out for myself.",
  ui_story_32250401_77_dialog_content = "Is this their base of operations?",
  ui_story_32250401_78_dialog_content = "Yes, elder. I tracked their leader all the way to this place.",
  ui_story_32250401_79_dialog_content = "He didn't realize he was being followed, and ordered his men to unload some traps and crossbows.",
  ui_story_32250401_80_dialog_content = "Some of those traps were still covered in blood!",
  ui_story_32250401_81_dialog_content = "Easy, Tiare. We have all the strength we need now, so just stick to the plan and we'll win.",
  ui_story_32250401_82_dialog_content = "<color=#e8d9bb>Awooo—</color>",
  ui_story_32250401_83_dialog_content = "Foxes, heed my call—",
  ui_story_32250401_84_dialog_content = "<color=#e8d9bb>A sharp whistle pierces the air as countless arctic foxes spring into action, dashing towards every corner of the manor.</color>",
  ui_story_32250401_85_dialog_content = "(Amazing... Tiare really can share her will with every single arctic fox!)",
  ui_story_32250401_86_dialog_content = "(Is this the power of the leader of the Arctic Fox Tribe?)",
  ui_story_32250401_87_dialog_content = "I'll help out too!",
  ui_story_32250401_88_dialog_content = "<color=#e8d9bb>After much hustling and bustling, a fox cries out from somewhere behind the manor.</color>",
  ui_story_32250401_89_dialog_content = "The firewood is in place and has been doused in oil, as well as the room housing their traps and crossbows. Once the fire is lit, nothing will be left behind.",
  ui_story_32250401_90_dialog_content = "You got all of that from a single howl? Are you sure you understood everything?",
  ui_story_32250401_91_dialog_content = "I can understand you perfectly fine, can't I?",
  ui_story_32250401_92_dialog_content = "Of course you can!",
  ui_story_32250401_93_dialog_content = "So why bother asking me that?",
  ui_story_32250401_94_dialog_content = "Uh... Never mind. Light the fire!",
  ui_story_32250401_95_dialog_content = "<color=#e8d9bb>Tiare gives another sharp, high-pitched whistle.</color>",
  ui_story_32250401_96_dialog_content = "Who's out there?",
  ui_story_32250401_97_dialog_content = "Ahh! Fire! Fire!",
  ui_story_32250401_98_dialog_content = "... Get in there and grab as many crossbows as you can!",
  ui_story_32250401_99_dialog_content = "Yes, sir!",
  ui_story_32250401_100_dialog_content = "You're not going anywhere!",
  ui_story_32250401_101_dialog_content = "Urgh—",
  ui_story_32250401_102_dialog_content = "Aaaaaahhh—",
  ui_story_32250401_103_dialog_content = "F-Foxes? What are they doing here—",
  ui_story_32250401_104_dialog_content = "You still have a lot to learn, it seems!",
  ui_story_32250401_105_dialog_content = "<color=#e8d9bb>Awooo—</color>",
  ui_story_32250401_106_dialog_content = "Urgh... S-Stay back, you animals!",
  ui_story_32250401_107_dialog_content = "(Most of them should be here by now... Looks like this is our chance...)",
  ui_story_32250401_108_dialog_content = "It's time for us to retreat, Tiare!",
  ui_story_32250401_109_dialog_content = "On it!",
  ui_story_32250401_110_dialog_content = "Hey! I said \"retreat,\" not \"pick me up\"!",
  ui_story_32250401_111_dialog_content = "Don't worry, you're very light!",
  ui_story_32250401_112_dialog_content = "Aaaaaahhh—",
  ui_story_32250401_113_dialog_content = "Please! Have mercy!",
  ui_story_32250401_114_dialog_content = "What would you know about mercy? How many times did you and your men ignore the cries of our fellow forest creatures as you slaughtered them?",
  ui_story_32250401_115_dialog_content = "Ah! It spoke! The fox spoke!",
  ui_story_32250401_116_dialog_content = "What the heck are you talking about?",
  ui_story_32250401_117_dialog_content = "That's him right there, boss!",
  ui_story_32250401_118_dialog_content = "Who are you people? N-Never mind... Please, you have to save us! These foxes have gone mad!",
  ui_story_32250401_119_dialog_content = "You're joking, right? You're the ones who captured them for your little arena, aren't you? Who else are they supposed to attack, huh?",
  ui_story_32250401_120_dialog_content = "A-Arena? What in the world are you talking about?",
  ui_story_32250401_121_dialog_content = "I had my doubts when I read that letter...",
  ui_story_32250401_122_dialog_content = "But now that I've seen your foxes, I know for a fact that you're trying to cut into my turf!",
  ui_story_32250401_123_dialog_content = "I-I have no idea what you're talking about! These foxes just appeared a few minutes ago, I swear!",
  ui_story_32250401_124_dialog_content = "Nice try, pal, but we're in Umbraton. If you didn't haul them over here from Northland, how could they get here?",
  ui_story_32250401_125_dialog_content = "Wait... I just remembered! They were being controlled by a woman and a young man! They were in my shop earlier!",
  ui_story_32250401_126_dialog_content = "Oh yeah? So where are they?",
  ui_story_32250401_127_dialog_content = "I-I'm not sure, but do you see that fox? It's bigger than the others, and I'm positive it's working for them! It can even talk!",
  ui_story_32250401_128_dialog_content = "Awooo! Roar—",
  ui_story_32250401_129_dialog_content = "You call that \"talking\"?",
  ui_story_32250401_130_dialog_content = "It's only pretending!",
  ui_story_32250401_131_dialog_content = "You're the only one pretending here, jerk! I'll teach you to mess with me on my own turf!",
  ui_story_32250401_132_dialog_content = "Alright, boys! Get these lowlifes out of my sight, but not before you rough 'em up good!",
  ui_story_32250401_133_dialog_content = "Get 'em—",
  ui_story_32250401_134_dialog_content = "Aaaaaahhhh—",
  ui_story_32250401_135_dialog_content = "... And that's how we dealt the finishing blow to those poachers. After that, they never set foot in our forest again, and peace finally returned to our home.",
  ui_story_32250401_136_dialog_content = "Awesome!",
  ui_story_32250401_137_dialog_content = "You're incredible, Tiare! Your Caelestite friend sounds super smart too!",
  ui_story_32250401_138_dialog_content = "Heehee... Of course he is! He happens to be the smartest person I know!",
  ui_story_32250401_139_dialog_content = "(There she goes telling that story again... It's a little too embarrassing to go over there right now, so I'll just wait.)",
  ui_story_32250401_140_dialog_content = "Hey, look! It's the super-smart Caelestite!",
  ui_story_32250401_141_dialog_content = "Why are you just standing around over there, PlayerName? Get over here!",
  ui_story_32250401_142_dialog_content = "Sir Novio says there's going to be an aurora tonight, and I want to take you to the best place to see it!",
  ui_story_32250401_143_dialog_content = "Wait! You're not gonna pick me up again, are you?",
  ui_story_32250401_144_dialog_content = "Alright! Let's get going!",
  ui_story_32250401_145_dialog_content = "Ahhhhh—"
}
return config
